import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64
.visible .entry tanh_kernel(
    .param .u64 param_in,
    .param .u64 param_out,
    .param .u64 param_n
)
{
    .reg .pred %p1;
    .reg .pred %p2;
    .reg .b32 %r1;
    .reg .b32 %r2;
    .reg .b32 %r3;
    .reg .b32 %r4;
    .reg .b64 %rd1;
    .reg .b64 %rd2;
    .reg .b64 %rd3;
    .reg .b64 %rd4;
    .reg .b64 %rd5;
    .reg .b64 %rd6;
    .reg .b64 %rd7;
    .reg .f32 %f1;
    .reg .f32 %f2;
    .reg .f32 %f3;
    .reg .f32 %f4;
    .reg .f32 %f5;
    .reg .f32 %f6;
    .reg .f32 %f7;
    .reg .f32 %f8;
    ld.param.u64 %rd1, [param_in];
    ld.param.u64 %rd2, [param_out];
    ld.param.u64 %rd3, [param_n];
    mov.u32 %r1, %ctaid.x;
    mov.u32 %r2, %ntid.x;
    mov.u32 %r3, %tid.x;
    mad.lo.u32 %r4, %r1, %r2, %r3;
    cvt.u64.u32 %rd4, %r4;
    // rd6 = base element index = thread_id * 4
    shl.b64 %rd6, %rd4, 2;
    setp.ge.u64 %p1, %rd6, %rd3;
    @%p1 bra DONE;
    // if base + 4 <= n take the vectorized path
    add.s64 %rd7, %rd6, 4;
    setp.le.u64 %p2, %rd7, %rd3;
    @!%p2 bra TAIL;
    // rd5 = byte offset = thread_id * 16 (16B aligned)
    shl.b64 %rd5, %rd4, 4;
    add.s64 %rd7, %rd1, %rd5;
    ld.global.v4.f32 {%f1, %f2, %f3, %f4}, [%rd7];
    tanh.approx.f32 %f5, %f1;
    tanh.approx.f32 %f6, %f2;
    tanh.approx.f32 %f7, %f3;
    tanh.approx.f32 %f8, %f4;
    add.s64 %rd7, %rd2, %rd5;
    st.global.v4.f32 [%rd7], {%f5, %f6, %f7, %f8};
    bra DONE;
TAIL:
    // scalar cleanup loop, rd6 holds current element index
TAIL_LOOP:
    setp.ge.u64 %p1, %rd6, %rd3;
    @%p1 bra DONE;
    shl.b64 %rd5, %rd6, 2;
    add.s64 %rd7, %rd1, %rd5;
    ld.global.f32 %f1, [%rd7];
    tanh.approx.f32 %f2, %f1;
    add.s64 %rd7, %rd2, %rd5;
    st.global.f32 [%rd7], %f2;
    add.s64 %rd6, %rd6, 1;
    bra TAIL_LOOP;
DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("tanh_kernel")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        numel = x.numel()
        out = torch.empty(x.size(), dtype=x.dtype, device=x.device)
        block_x = 256
        grid_x = (numel + block_x * 4 - 1) // (block_x * 4)
        module = _get_ptx_module()
        module.launch(
            "tanh_kernel",
            grid=(grid_x, 1, 1),
            block=(block_x, 1, 1),
            arguments=[x, out, i64(numel)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return out
        block_x = 256
        grid_x = (numel + block_x * 4 - 1) // (block_x * 4)

